INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(65734501, 'Rescue-ACE Air Lifter', '救援王牌 空中吊挂者', 'R－ACEエアホイスター', 'Effect Monster', 'Warrior', 'FIRE', 4, 1700, 1700, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「救援ACE队」魔法卡加入手卡。 ②：对方把怪兽的效果在场上发动时，把手卡·场上的这张卡解放才能发动。从手卡把「救援ACE队 空中起吊员」以外的1只「救援ACE队」怪兽特殊召唤。'),
(2725599, 'Rescue-ACE Arbitrator', '救援王牌 裁焰者', 'R－ACEアビトレイター', 'Link Monster', 'Machine', 'FIRE', NULL, 3000, NULL, '炎属性怪兽2只以上 自己对「救援ACE队 仲裁消防战车」1回合只能有1次特殊召唤，那个②的效果1回合可以使用最多2次。 ①：这张卡连接召唤的场合才能发动。从自己的卡组·墓地把1只「救援ACE队 消防栓」或1张「救援ACE队总部」加入手卡。 ②：自己把「救援ACE队」速攻魔法·通常陷阱卡发动的场合，以对方场上1张卡为对象才能发动。那张卡破坏。'),
(64612053, 'Rescue-ACE Fire Attacker', '救援王牌 火焰攻击机', 'R－ACEファイア・アタッカー', 'Effect Monster', 'Machine', 'FIRE', 6, 2200, 2200, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「救援ACE队 空中灭火机」以外的「救援ACE队」怪兽召唤·特殊召唤的场合才能发动。这张卡从手卡特殊召唤。 ②：抽卡以外的方法让对方手卡有卡加入的场合才能发动。自己抽2张。那之后，选自己1张手卡丢弃。'),
(90000652, 'Rescue-ACE Fire Engine', '救援王牌 火焰驱动机', 'R－ACEファイア・エンジン', 'Effect Monster', 'Machine', 'FIRE', 7, 2500, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「救援ACE队 消防战车人」以外的「救援ACE队」怪兽召唤·特殊召唤的场合才能发动。这张卡从手卡特殊召唤。 ②：对方场上有怪兽特殊召唤的场合才能发动。从自己的手卡·卡组·墓地把1只4星以下的「救援ACE队」怪兽特殊召唤。'),
(63899465, 'Rescue-ACE HQ', '救援王牌总司令部', 'R－ACEヘッドクオーター', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要对方场上有怪兽存在，自己场上的「救援ACE队」怪兽的攻击力·守备力上升500。 ②：自己在通常召唤外加上只有1次，自己主要阶段可以把1只「救援ACE队」怪兽召唤。 ③：1回合1次，以自己的墓地·除外状态的4张「救援ACE队」卡为对象才能发动。那些卡回到卡组。那之后，自己抽1张。'),
(37617348, 'Rescue-ACE Hydrant', '救援王牌 消防栓', 'R－ACEハイドラント', 'Effect Monster', 'Machine', 'FIRE', 1, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：只要自己场上有「救援ACE队 消防栓」以外的「救援ACE队」怪兽存在，对方怪兽不能选择这张卡作为攻击对象，对方不能以此作为效果的对象。 ②：只要这张卡在怪兽区域存在，自己的「救援ACE队」卡的效果盖放的1张速攻魔法·陷阱卡在盖放的回合也能发动。 ③：自己主要阶段才能发动。从卡组把「救援ACE队 消防栓」以外的1只「救援ACE队」怪兽加入手卡。'),
(38339996, 'Rescue-ACE Impulse', '救援王牌 脉冲消防员', 'R－ACEインパルス', 'Effect Monster', 'Warrior', 'FIRE', 3, 1500, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。选对方场上1只攻击力最高的效果怪兽。这个回合，双方不能把那只表侧表示怪兽的场上发动的效果发动。 ②：对方把怪兽的效果在场上发动时，把手卡·场上的这张卡解放才能发动。从卡组把1只机械族「救援ACE队」怪兽特殊召唤。'),
(91222209, 'Rescue-ACE Monitor', '救援王牌 水炮灭火者', 'R－ACEイントルーダー', 'Effect Monster', 'Warrior', 'FIRE', 4, 1800, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「救援ACE队」陷阱卡加入手卡。 ②：对方把场上的怪兽的效果发动时，把手卡·场上的这张卡解放，以「救援ACE队 双脉冲炮灭火员」以外的自己墓地1只「救援ACE队」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(41443249, 'Rescue-ACE Preventer', '救援王牌 空中防灾机', 'R－ACEプリベンター', 'Effect Monster', 'Machine', 'FIRE', 8, 2800, 2800, '这个卡名的①②③的效果1回合各能使用1次。 ①：从自己墓地把1张「救援ACE队」卡除外才能发动。这张卡从手卡特殊召唤。 ②：自己·对方回合，自己场上有其他的「救援ACE队」怪兽存在的场合，以对方场上1只效果怪兽为对象才能发动。那只怪兽变成里侧守备表示。 ③：这张卡被送去墓地的场合，以8星怪兽以外的自己的除外状态的1只「救援ACE队」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(47425162, 'Rescue-ACE Quick Attacker', '救援王牌 迅猛攻击机', 'R－ACEクイック・アタッカー', 'Effect Monster', 'Warrior', 'FIRE', 3, 1400, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·场上（表侧表示）让这张卡以外的1张「救援ACE队」卡回到卡组才能发动。这张卡从手卡特殊召唤。 ②：把这张卡解放才能发动。从卡组把1只「救援ACE队」怪兽加入手卡。那之后，只有对方场上才有怪兽存在的场合，可以把加入手卡的那只怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是炎属性怪兽不能从额外卡组特殊召唤。'),
(37495766, 'Rescue-ACE Turbulence', '救援王牌 爆流涡轮机', 'R－ACEタービュランス', 'Effect Monster', 'Machine', 'FIRE', 9, 3000, 3000, '这个卡名的①②③的效果1回合各能使用1次。 ①：从自己墓地把2张「救援ACE队」卡除外才能发动。这张卡从手卡特殊召唤。 ②：自己主要阶段才能发动。从卡组把最多4张「救援ACE队」速攻魔法·通常陷阱卡在自己场上盖放（同名卡最多1张）。 ③：自己场上的其他卡因对方的效果从场上离开的场合，以场上1张卡为对象才能发动。那张卡破坏。'),
(99984170, 'RESCUE!', '救援！', 'RESCUE！', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「救援ACE队」卡使用。这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只「救援ACE队」怪兽为对象才能发动（自己场上有「救援ACE队 消防栓」存在的场合，也能作为代替以对方墓地1只怪兽为对象）。那只怪兽在自己场上特殊召唤。'),
(24311595, 'Rescueroid', '救援机人', 'レスキューロイド', 'Effect Monster', 'Machine', 'FIRE', 6, 1600, 1800, '只要这张卡在自己场上表侧表示存在，自己场上存在的名字带有「机人」的怪兽被战斗破坏送去墓地时，可以使那只怪兽回到手卡。'),
(23912837, 'Resh Shaddoll Incarnation', '阳影依变生', '影光の聖選士', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己墓地1只「影依」怪兽为对象才能发动。那只怪兽表侧守备表示或里侧守备表示特殊召唤。 ②：可以从自己墓地把这张卡和1张「影依」卡除外，从以下效果选择1个发动。 ●自己场上1只里侧表示怪兽变成表侧守备表示。 ●自己场上1只表侧表示怪兽变成里侧守备表示。'),
(62420419, 'Reshef the Dark Being', '大邪神 雷瑟夫', '大邪神 レシェフ', 'Ritual Effect Monster', 'Fiend', 'LIGHT', 8, 2500, 1500, '「大邪神的仪式」降临。从手卡丢弃1张魔法卡。结束阶段前获得对方场上1只怪兽的控制权。这个效果1个回合只能使用1次。'),
(92610868, 'ReSolfachord Dreamia', '来音服和弦・多利米娅', 'レドレミコード・ドリーミア', 'Pendulum Effect Monster', 'Fairy', 'WIND', 2, 600, 400, '这个卡名的①的怪兽效果1回合只能使用1次。 ①：自己的灵摆区域有「七音服」卡存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己的灵摆区域有奇数的灵摆刻度存在，自己场上的「七音服」灵摆怪兽卡被对方的效果破坏的场合，可以作为那1张破坏的卡的代替而把这张卡破坏。'),
(26864586, 'Resonance Device', '共振装置', '共振装置', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的2只相同种族·属性的怪兽发动。选择的1只怪兽的等级直到结束阶段时变成和另1只怪兽的等级相同。'),
(96938986, 'Resonance Insect', '共振虫', '共振虫', 'Effect Monster', 'Insect', 'EARTH', 4, 1000, 700, '①：这张卡从场上送去墓地的场合才能发动。从卡组把1只5星以上的昆虫族怪兽加入手卡。 ②：这张卡被除外的场合才能发动。从卡组把「共振虫」以外的1只昆虫族怪兽送去墓地。'),
(59593925, 'Resonant Destruction', '共鸣破', '共鳴破', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，每次名字带有「共鸣者」的怪兽作为同调素材送去墓地，选择对方场上存在的1张卡破坏。这张卡在发动后第2次的自己的结束阶段时破坏。'),
(23008320, 'Resonator Call', '呼叫共鸣者', 'コール・リゾネーター', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组把1只「共鸣者」怪兽加入手卡。'),
(8559524, 'Resonator Command', '指挥共鸣者', 'コマンド・リゾネーター', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡丢弃1只「共鸣者」怪兽才能发动。从卡组把1只4星以下的恶魔族怪兽加入手卡。'),
(15576074, 'Resonator Engine', '共鸣者引擎', 'リゾネーター・エンジン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地2只「共鸣者」怪兽为对象才能发动。从卡组把1只4星怪兽加入手卡，作为对象的怪兽回到卡组。'),
(8951260, 'Respect Play', '正正堂堂', '正々堂々', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '双方玩家必须在各自的回合把手卡全部持续公开。'),
(98552723, 'Restoration of the Monarchs', '再临的帝王', '再臨の帝王', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只攻击力2400/守备力1000的怪兽或者攻击力2800/守备力1000的怪兽为对象才能把这张卡发动。那只怪兽效果无效守备表示特殊召唤，把这张卡装备。这张卡从场上离开时那只怪兽破坏。 ②：怪兽上级召唤的场合，装备怪兽可以作为2只的数量解放。'),
(74163487, 'Restoration Point Guard', '还原点控球后卫', 'レストレーション・ポイントガード', 'Link Monster', 'Cyberse', 'DARK', NULL, 1000, NULL, '电子界族怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，这张卡以外的连接怪兽连接召唤成功的场合发动。这个回合，这张卡不会被战斗·效果破坏。 ②：这张卡在墓地存在，这张卡为素材作连接召唤的连接怪兽被对方的效果破坏的场合才能发动。这张卡特殊召唤。'),
(99518961, 'Restructer Revolution', '革命', '革命', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '对方受到（对方的手卡数×200）的伤害。'),
(49082032, 'Resurgam Xyz', '再起超量', 'リサーガム・エクシーズ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己场上的超量怪兽的攻击力上升800。 ②：1回合1次，从手卡丢弃1张魔法卡，以自己场上1只超量怪兽为对象才能发动。和那只自己怪兽相同种族而阶级高1阶的1只「混沌No.」怪兽或者「混沌超量」怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。把「升阶魔法」魔法卡以外丢弃发动的场合，这个效果特殊召唤的怪兽在结束阶段回到持有者的额外卡组。'),
(39399168, 'Resurrection of Chakra', '查克拉的复活', 'チャクラの復活', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「查克拉」的降临必要。必须从场上或者手札，牺牲奉献等级合计为7个以上的卡。'),
(55702233, 'Ret-time Reviver Emit-ter', '锦丝幽魂悠思景', '生きる偲びのシルキィ', 'Tuner Monster', 'Fairy', 'DARK', 2, 800, NULL, '这个卡名的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在的场合，以自己以及对方场上的表侧表示怪兽各1只为对象才能发动。那些怪兽变成里侧守备表示，这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(46502744, 'Retaliating "C"', '应战的Z', '応戦するG', 'Effect Monster', 'Insect', 'EARTH', 4, 1400, 1400, '①：包含把怪兽特殊召唤效果的魔法卡由对方发动时才能发动。这张卡从手卡特殊召唤。 ②：只要这张卡的①的效果特殊召唤的这张卡在怪兽区域存在，被送去墓地的卡不去墓地而除外。 ③：这张卡从场上送去墓地的场合才能发动。从卡组把「应战的G」以外的1只攻击力1500以下的昆虫族·地属性怪兽加入手卡。'),
(22747316, 'Retort', '以牙还牙', 'しっぺ返し', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '和自己墓地存在的魔法·陷阱卡同名的卡由对方发动时才能发动。那个发动无效并破坏。那之后，和用这个效果把发动无效的卡同名的卡可以从自己墓地选1张加入手卡。'),
(47247413, 'Return', '退回', '差し戻し', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方把墓地的卡加入手卡时才能发动。对方让加入手卡的那1张卡回到卡组。'),
(27174286, 'Return from the Different Dimension', '来自异次元的归还', '異次元からの帰還', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把基本分支付一半才能发动。从游戏中除外的自己怪兽尽可能在自己场上特殊召唤。这个效果特殊召唤的怪兽在结束阶段时从游戏中除外。'),
(19827717, 'Return of the Doomed', '死者生还', '死者の生還', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己的手卡的1张怪兽卡丢弃去墓地。这个回合因为战斗被破坏送去自己的墓地的怪兽1只回合结束的时候回到手卡。'),
(6853254, 'Return of the Dragon Lords', '复活福音', '復活の福音', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只7·8星的龙族怪兽为对象才能发动。那只怪兽特殊召唤。 ②：自己场上的龙族怪兽被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(97227123, 'Return of the Duelist', '决斗者归来', 'リターン・オブ・ザ・デュエリスト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：场上或者自己或对方的墓地有超量怪兽存在的场合才能发动。从自己的卡组·墓地把1张装备魔法卡加入手卡。'),
(61466310, 'Return of the Monarchs', '帝王的开岩', '帝王の開岩', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '「帝王的开岩」的②的效果1回合只能使用1次。 ①：只要这张卡在魔法与陷阱区域存在，自己不能从额外卡组把怪兽特殊召唤。 ②：自己以表侧表示对怪兽的上级召唤成功时，可以从以下效果选择1个发动。 ●和那只怪兽卡名不同的1只攻击力2400/守备力1000的怪兽从卡组加入手卡。 ●和那只怪兽卡名不同的1只攻击力2800/守备力1000的怪兽从卡组加入手卡。'),
(39387565, 'Return of the Red-Eyes', '真红眼之铠旋', '真紅眼の鎧旋', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '「真红眼的铠旋」的①②的效果1回合各能使用1次。 ①：自己场上有「真红眼」怪兽存在的场合，以自己墓地1只通常怪兽为对象才能把这个效果发动。那只怪兽特殊召唤。 ②：这张卡被对方的效果破坏送去墓地的场合，以自己墓地1只「真红眼」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(46874015, 'Return of the Six Samurai', '六武众推参！', '六武衆推参！', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地1只名字带有「六武众」的怪兽才能发动。选择的怪兽从墓地特殊召唤。这个效果特殊召唤的怪兽在这个回合的结束阶段时破坏。'),
(91742238, 'Return of the Zombies', '不死者归来', 'リターン・オブ・アンデット', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：选场上1只不死族怪兽除外。那之后，从那个控制者墓地选1只不死族怪兽在那持有者场上守备表示特殊召唤。 ②：这张卡在墓地存在的场合才能发动。选除外的1只自己的不死族怪兽回到卡组，这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(10537981, 'Return Soul', '回魂', 'リターンソウル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '结束阶段时才能发动。可以使这个回合被破坏的在墓地存在的最多3只怪兽回到持有者卡组。'),
(3072077, 'Return Zombie', '回归僵尸', 'リターン・ゾンビ', 'Effect Monster', 'Zombie', 'DARK', 4, 1000, 1600, '自己的准备阶段时，这张卡在墓地存在并且自己手卡是0张的场合，可以支付500基本分把这张卡加入手卡。'),
(101303093, 'Returned Dino Daneen', NULL, NULL, 'Effect Monster', 'Dinosaur', 'WATER', 1, 400, 1200, NULL),
(24892828, 'Returned of the Tistina', '提斯蒂娜的归还之子', 'ティスティナの還り仔', 'Effect Monster', 'Aqua', 'FIRE', 2, 500, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，以「提斯蒂娜之还仔」以外的自己场上1只「提斯蒂娜」怪兽为对象才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡的等级变成和作为对象的怪兽相同。 ②：这张卡在墓地存在的场合，以自己场上1只水族超量怪兽为对象才能发动。把这张卡作为那只怪兽的超量素材。'),
(18319762, 'Revealer of the Ice Barrier', '冰结界的照魔师', '氷結界の照魔師', 'Effect Monster', 'Spellcaster', 'WATER', 4, 1700, 1000, '这个卡名的②③的效果1回合各能使用1次。 ①：只要自己场上有其他的「冰结界」怪兽存在，对方不能上级召唤。 ②：丢弃1张手卡才能发动。从卡组把1只「冰结界」调整特殊召唤。这个效果的发动后，直到回合结束时自己不是水属性怪兽不能特殊召唤。 ③：自己为让「冰结界」怪兽的效果发动而把手卡送去墓地的场合或者丢弃的场合，可以作为那1张卡的代替而把墓地的这张卡除外。'),
(42104806, 'Revelation of Hope', '希望之天启', '希望の天啓', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只表侧表示的龙族·8星怪兽送去墓地才能发动。把1只龙族·8阶的超量怪兽当作超量召唤从额外卡组特殊召唤。'),
(7986397, 'Revendread Evolution', '复仇尸者・觉醒', 'リヴェンデット・バース', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「复仇死者」仪式怪兽的降临必需。这个卡名的卡在1回合只能发动1张。 ①：等级合计直到变成和仪式召唤的怪兽相同为止，把自己的手卡·场上的怪兽解放或者作为解放的代替而从卡组把「复仇死者」怪兽（最多1只）送去墓地，从自己的手卡·墓地把1只「复仇死者」仪式怪兽仪式召唤。这个效果仪式召唤的怪兽在下个回合的结束阶段破坏。'),
(34093683, 'Revendread Executor', '复仇尸者・制裁者', 'リヴェンデット・エグゼクター', 'Ritual Effect Monster', 'Zombie', 'DARK', 8, 3000, NULL, '「复仇死者」仪式魔法卡降临。这个卡名的③的效果1回合只能使用1次。 ①：这张卡只要在怪兽区域存在，卡名当作「归魂复仇死者·屠魔侠」使用。 ②：只要仪式召唤的这张卡在怪兽区域存在，对方不能把自己场上的其他卡作为效果的对象。 ③：仪式召唤的这张卡被战斗或者对方的效果破坏的场合才能发动。从卡组把1张「复仇死者」卡加入手卡。'),
(94666032, 'Revendread Origin', '复仇尸者・诞生', 'リヴェンデット・ボーン', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「复仇死者」仪式怪兽的降临必需。 ①：等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放或者作为解放的代替而把自己墓地的不死族怪兽除外，从自己的手卡·墓地把1只「复仇死者」仪式怪兽仪式召唤。 ②：自己场上的「归魂复仇死者·屠魔侠」被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(4388680, 'Revendread Slayer', '复仇尸者・屠戮者', 'リヴェンデット・スレイヤー', 'Ritual Effect Monster', 'Zombie', 'DARK', 6, 2400, NULL, '「复仇死者」仪式魔法卡降临。这个卡名的②的效果1回合只能使用1次。 ①：这张卡和对方怪兽进行战斗的伤害计算时1次，从自己墓地把1只不死族怪兽除外才能发动。这张卡的攻击力上升300。 ②：仪式召唤的这张卡被送去墓地的场合才能发动。从卡组把1张仪式魔法卡加入手卡，从卡组把1只「复仇死者」怪兽送去墓地。'),
(51686645, 'Revenge Rally', '卷怒重来', '捲怒重来', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以对方场上1只表侧表示怪兽为对象才能把这张卡发动。这张卡当作攻击力·守备力上升500的装备卡使用给那只对方怪兽装备。 ②：装备怪兽从场上离开让这张卡被送去墓地的场合发动。自己从卡组抽1张。这张卡是这个回合发动的场合作为代替让以下效果适用。 ●自己从卡组抽2张，那之后选1张手卡丢弃。'),
(36690018, 'Reversal of Fate', '逆转的命运', '逆転する運命', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只名字带有「秘仪之力」的怪兽发动。选择怪兽用投掷硬币的里表所得效果变成相反。'),
(5990062, 'Reversal Quiz', '大逆转谜题', '大逆転クイズ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '将自己手卡和场上的卡全部送去墓地。猜自己卡组最上面1张卡的种类（魔法/陷阱/怪兽），若猜对，则将自己与对方的基本分值互换。'),
(94950218, 'Reverse Breaker', '埋伏破坏', 'リバース・ブレイカー', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「希望皇 霍普」的怪兽才能装备。装备怪兽攻击宣言时，选择对方场上1张魔法·陷阱卡破坏。对方不能对应这个效果的发动把魔法·陷阱卡发动。'),
(90640901, 'Reverse Buster', '埋伏破坏者', 'リバース・バスター', 'Effect Monster', 'Fiend', 'LIGHT', 4, 1500, NULL, '这张卡只能向里侧守备表示怪兽攻击。这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。这张卡向里侧守备表示怪兽攻击的场合，可以不进行伤害计算以里侧守备表示的状态把那只怪兽破坏。'),
(94156050, 'Reverse Glasses', '颠倒眼镜', '逆さ眼鏡', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '场上表侧表示存在的全部怪兽的攻击力直到结束阶段时变成一半。'),
(67248304, 'Reverse Jar', '反转壶', 'リバースポッド', 'Flip Effect Monster', 'Rock', 'EARTH', 3, 800, 900, '这个卡名的效果1回合只能使用1次。 ①：这张卡反转的场合发动。这张卡以外的场上的怪兽全部变成里侧守备表示。那之后，场上的表侧表示的魔法·陷阱卡全部回到持有者手卡。并且，双方各自可以再把最多有这个效果回到自身手卡的卡数量的魔法·陷阱卡从手卡盖放。'),
(18302224, 'Reverse of Neos', '新宇侠的逆转', 'リバース・オブ・ネオス', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的名字带有「新宇」的融合怪兽被破坏时才能发动。从自己卡组把1只「元素英雄 新宇侠」攻击表示特殊召唤。这个效果特殊召唤的「元素英雄 新宇侠」的攻击力只要在场上表侧表示存在上升1000，这个回合的结束阶段时破坏。'),
(93775296, 'Reverse Reuse', '反转重用', 'リバース・リユース', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地最多2只反转怪兽为对象才能发动。那些怪兽表侧守备表示或者里侧守备表示在对方场上特殊召唤。'),
(77622396, 'Reverse Trap', '天邪鬼的诅咒', 'あまのじゃくの呪い', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '直到发动回合的结束阶段时，攻击力·守备力的上升·下降的效果变成相反。'),
(45702357, 'Reversible Beetle', '双面可逆甲虫', 'リバーシブル・ビートル', 'Effect Monster', 'Insect', 'EARTH', 3, 1100, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合发动。这张卡以及和这张卡相同纵列的怪兽全部变成里侧守备表示。 ②：这张卡反转的场合发动。这张卡以及和这张卡相同纵列的表侧表示怪兽全部回到持有者卡组。'),
(93912845, 'Revival Gift', '复活礼物', 'リバイバル・ギフト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地存在的1只调整特殊召唤。这个效果特殊召唤的怪兽的效果无效化。在对方场上把2只「礼物魔衍生物」（恶魔族·暗·3星·攻/守1500）特殊召唤。'),
(87347365, 'Revival Golem', '再生魔像', 'リバイバルゴーレム', 'Effect Monster', 'Rock', 'EARTH', 4, 100, 2100, '这个卡名的效果1回合只能使用1次。 ①：这张卡从卡组送去墓地的场合，从以下效果选择1个发动。 ●这张卡特殊召唤。 ●这张卡加入手卡。'),
(31709826, 'Revival Jam', '再生史莱姆', 'リバイバルスライム', 'Effect Monster', 'Aqua', 'WATER', 4, 1500, 500, '①：这张卡被战斗破坏送去墓地时，支付1000基本分才能发动。下次的自己准备阶段这张卡从墓地守备表示特殊召唤。'),
(31066283, 'Revival of Dokurorider', '骷髅骑手的复活', 'スカルライダーの復活', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「骷髅骑手」降临必要。场上和手卡加起来总共6颗星以上的怪兽作祭品。'),
(39967326, 'Revival of the Immortals', '过早的复活', '早すぎた復活', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地存在的1只名字带有「地缚神」的怪兽发动。选择的怪兽在自己场上特殊召唤。这个效果特殊召唤的怪兽在那个回合不能攻击宣言。此外，这个效果特殊召唤的怪兽进行战斗的场合，对方玩家受到的战斗伤害变成0。'),
(12469386, 'Revival Rose', '再开的大朵蔷薇', '返り咲く薔薇の大輪', 'Effect Monster', 'Plant', 'DARK', 4, 1300, 1300, '自己场上存在的5星以上的植物族怪兽被破坏的场合，墓地存在的这张卡可以在自己场上特殊召唤。'),
(89226534, 'Revival Swarm', '苏生之蜂玉', '蘇生の蜂玉', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以自己墓地1只「蜂军」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：把墓地的这张卡除外，以自己场上1只昆虫族怪兽为对象才能发动。那只怪兽直到下个回合的结束时不会被战斗·效果破坏。'),
(5309481, 'Revived King Ha Des', '苏醒魔王 哈迪斯', '蘇りし魔王 ハ・デス', 'Synchro Monster', 'Zombie', 'DARK', 6, 2450, NULL, '「僵尸带菌者」＋调整以外的不死族怪兽1只以上 只要这张卡在场上表侧表示存在，自己场上存在的不死族怪兽战斗破坏的效果怪兽的效果无效化。'),
(49469105, 'Revoke Fusion', '融合破弃', '融合破棄', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把1张「融合」从手卡丢弃去墓地发动。把融合卡组存在的1只融合怪兽送去墓地，那只融合怪兽记述的1只融合素材怪兽从手卡特殊召唤。这个效果特殊召唤的怪兽在这个回合的结束阶段时送去墓地。'),
(97682931, 'Revolution Synchron', '革命同步士', 'レボリューション・シンクロン', 'Tuner Monster', 'Machine', 'EARTH', 3, 900, 1400, '这个卡名的①的效果1回合只能使用1次，②的效果在决斗中只能使用1次。 ①：「动力工具」同调怪兽或者7·8星的龙族同调怪兽同调召唤的场合，手卡的这张卡也能作为同调素材。 ②：这张卡在墓地存在，自己场上有7星以上的同调怪兽存在的场合才能发动。自己卡组最上面的卡送去墓地，这张卡特殊召唤。这个效果特殊召唤的这张卡的等级变成1星。'),
(76136345, 'Revolving Switchyard', '回转调车', '転回操車', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上有机械族·地属性·10星怪兽召唤·特殊召唤的场合才能发动。从卡组把1只攻击力1800以上的机械族·地属性·4星怪兽特殊召唤。这个效果特殊召唤的怪兽的等级变成10星。这个效果的发动后，直到回合结束时对方受到的战斗伤害变成0。 ②：把自己1张手卡送去墓地才能发动。从卡组把1只机械族·地属性·10星怪兽加入手卡。'),
(28004531, 'Rex, Freight Fur Hire', '空牙团的载货 雷克斯', '空牙団の積荷 レクス', 'Effect Monster', 'Dinosaur', 'EARTH', 2, 300, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「空牙团」魔法·陷阱卡加入手卡。 ②：自己·对方的主要阶段，自己场上有「空牙团」怪兽存在的场合，把墓地的这张卡除外，以自己墓地1张「空牙团」卡为对象才能发动。那张卡加入手卡。作为对象的卡是怪兽的场合，也能不加入手卡特殊召唤。'),
(47647354, 'Rex, Ride Fur Hire', '空牙团的疾风 雷克斯', '空牙団の疾風 レクス', 'Effect Monster', 'Dinosaur', 'WIND', 5, 2000, 1200, '这个卡名的①的效果1回合只能使用1次。 ①：把手卡的这张卡给对方观看才能发动。从手卡把「空牙团的疾风 雷克斯」以外的1只「空牙团」怪兽特殊召唤。那之后，这张卡特殊召唤。 ②：「空牙团」卡以外的效果从卡组让卡加入对方手卡的场合，若自己场上有其他的「空牙团」怪兽存在则能发动。自己抽1张。'),
(1259814, 'RGB Rainbowlution', '千六百七十七万工房', '千六百七十七万工房', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的种族变成机械族，那个属性也当作「光」「暗」「地」「水」「炎」「风」使用。'),
(62403074, 'Rhaimundos of the Red Sword', '赤剑之莱蒙多斯', '赤き剣のライムンドス', 'Normal Monster', 'Warrior', 'EARTH', 4, 1200, 1300, '持有赤红炎剑的战士。利用火焰束缚来封住行动。'),
(83957459, 'Rhinotaurus', '犀牛头人', 'ライノタウルス', 'Effect Monster', 'Beast-Warrior', 'FIRE', 4, 1800, 600, '同1次的战斗阶段中，自己场上存在的怪兽的战斗把对方怪兽2只以上破坏的场合，这张卡在那次战斗阶段中可以作2次攻击。'),
(37534148, 'Ribbon of Rebirth', '苏生缎带', 'リボーンリボン', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽被战斗破坏送去墓地的场合，那个回合的结束阶段时把那只怪兽在自己场上特殊召唤。'),
(65687442, 'Ride of the Valkyries', '女武神的骑行', 'Walkuren Ritt', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：从手卡把「女武神」怪兽任意数量特殊召唤（同名卡最多1张）。这个效果把3只以上的怪兽特殊召唤的场合，直到下个回合的结束时自己受到的战斗伤害变成0。这张卡发动的回合的结束阶段，自己场上的怪兽全部回到持有者卡组。 ②：把墓地的这张卡除外才能发动。从卡组把1张「时间女神的恶作剧」加入手卡。'),
(14235211, 'Rider of the Storm Winds', '暴风龙之防人', '暴風竜の防人', 'Tuner Monster', 'Dragon', 'LIGHT', 1, 500, 200, '自己的主要阶段时，手卡或者自己场上的这只怪兽可以当作装备卡使用给自己场上1只龙族的通常怪兽装备。这张卡当作装备卡使用而装备中的场合，装备怪兽向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。此外，这张卡的装备怪兽被破坏的场合，作为代替把这张卡破坏。'),
(70903634, 'Right Arm of the Forbidden One', '被封印者的右臂', '封印されし者の右腕', 'Normal Monster', 'Spellcaster', 'DARK', 1, 200, 300, '被封印的右腕。假若解开封印，能得无限之力。'),
(8124921, 'Right Leg of the Forbidden One', '被封印者的右足', '封印されし者の右足', 'Normal Monster', 'Spellcaster', 'DARK', 1, 200, 300, '被封印的右足。假若解开封印，能得无限之力。'),
(11845050, 'Right-Hand Shark', '右手鲨', 'ライトハンド・シャーク', 'Effect Monster', 'Fish', 'WATER', 4, 1500, 1300, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡召唤时才能发动。从卡组把1只「左手鲨」加入手卡。 ②：这张卡在墓地存在，自己场上没有怪兽存在的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ③：只用包含场上的这张卡的水属性怪兽为素材作超量召唤的怪兽得到以下效果。 ●这张卡不会被战斗破坏。'),
(60071928, 'Righty Driver', '右起子', 'ライティ・ドライバー', 'Tuner Monster', 'Machine', 'EARTH', 1, 100, 300, '这张卡可以作为「同调士」调整的代替而成为同调素材。这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤成功的场合才能发动。从自己的手卡·卡组·墓地选1只「左起子」特殊召唤。'),
(39180960, 'Rigorous Reaver', '再造的死神', 'リグラス・リーパー', 'Flip Effect Monster', 'Plant', 'FIRE', 3, 1600, 100, '①：这张卡反转的场合发动。双方玩家各自选自己1张手卡丢弃。 ②：这张卡被和怪兽的战斗破坏的场合发动。那只怪兽的攻击力·守备力下降500。'),
(96162588, 'Rikka Flurries', '六花风花', '六花の風花', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上的「六花」怪兽被解放的场合才能发动。对方必须把自身场上1只怪兽解放。 ②：对方结束阶段，植物族怪兽以外的表侧表示怪兽在自己场上存在的场合发动。这张卡破坏。'),
(69164989, 'Rikka Glamour', '六花绚烂', '六花絢爛', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。这张卡也能把自己场上1只植物族怪兽解放来发动。 ①：从卡组把1只「六花」怪兽加入手卡。把怪兽解放来把这张卡发动的场合，再把和加入手卡的怪兽是卡名不同并是原本等级相同的1只植物族怪兽从卡组加入手卡。'),
(76869711, 'Rikka Konkon', '六花来来', '六花来々', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上有「六花」怪兽存在的场合才能发动。从卡组选1张「六花」魔法·陷阱卡在自己的魔法与陷阱区域盖放。这个效果的发动后，直到回合结束时自己不是植物族怪兽不能特殊召唤。 ②：1回合1次，自己为让「六花」卡的效果发动而把自己场上的植物族怪兽解放的场合，可以作为自己场上1只植物族怪兽的代替而把对方场上1只表侧表示怪兽解放。'),
(71734607, 'Rikka Petal', '六花的一瓣', '六花のひとひら', 'Effect Monster', 'Plant', 'WATER', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从卡组选「六花的一瓣」以外的1只「六花」怪兽加入手卡或送去墓地。这个效果的发动后，直到回合结束时自己不是植物族怪兽不能特殊召唤。 ②：这张卡在墓地存在，自己场上没有怪兽存在的场合或者自己场上的怪兽只有植物族怪兽的场合，对方结束阶段才能发动。这张卡特殊召唤。'),
(132308, 'Rikka Princess', '六花的白姬', '六花のしらひめ', 'Effect Monster', 'Plant', 'WATER', 4, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。这张卡从手卡特殊召唤。只要这个效果特殊召唤的这张卡在怪兽区域表侧表示存在，自己不是植物族怪兽不能特殊召唤。 ②：自己场上有「六花」怪兽存在，对方把怪兽的效果发动时，让手卡·墓地的这张卡回到卡组，把自己场上1只植物族怪兽解放才能发动。那个发动的效果无效。'),
(3828844, 'Rikka Queen Strenna', '六花圣花环', '六花聖ストレナエ', 'XYZ Monster', 'Plant', 'WATER', 4, 2000, 2000, '4星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除，以自己墓地1只植物族怪兽或者1张「六花」卡为对象才能发动。那张卡加入手卡。 ②：持有超量素材的这张卡被解放的场合才能发动。从自己的额外卡组·墓地选1只5阶以上的植物族超量怪兽特殊召唤。那之后，可以把这张卡在那只怪兽下面重叠作为超量素材。'),
(68941332, 'Rikka Sheet', '六花薄冰', '六花の薄氷', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。这张卡也能把自己场上1只植物族怪兽解放来发动。 ①：以对方场上1只表侧表示怪兽为对象才能发动。这个回合，那只表侧表示怪兽不能把场上发动的效果发动。把怪兽解放来把这张卡发动的场合，再把那只怪兽的控制权直到结束阶段得到。这个效果得到控制权的怪兽变成植物族。'),
(32557233, 'Rikka Tranquility', '六花深深', '六花深々', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。这张卡也能把自己场上1只植物族怪兽解放来发动。 ①：从自己墓地选1只「六花」怪兽守备表示特殊召唤。把怪兽解放来把这张卡发动的场合，再从自己墓地选1只植物族怪兽守备表示特殊召唤。'),
(72498838, 'Rilliona, the Magistus of Verre', '伟魔贤者 结晶之桑德里永', '結晶の大賢者サンドリヨン', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 800, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，可以从以下效果选择1个发动。 ●从卡组把1张「大贤者」魔法·陷阱卡加入手卡。 ●选除外的1只自己的4星以下的魔法师族怪兽回到墓地。 ②：把墓地的这张卡除外，以自己场上1只「大贤者」怪兽为对象才能发动。从自己墓地选1只4星以外的「大贤者」怪兽当作装备卡使用给作为对象的怪兽装备。'),
(74689476, 'Rilliona, the Wondrous Magistus Witch Wardrobe', '伟魔女巫 结晶之桑德里永', '結晶の魔女サンドリヨン', 'XYZ Monster', 'Spellcaster', 'LIGHT', 4, 1000, 2800, '属性不同的魔法师族4星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除才能发动。从卡组把1只「大贤者」怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是「大贤者」怪兽不能从额外卡组特殊召唤。 ②：这张卡装备中的场合，以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。'),
(51409648, 'Rindbrumm the Striking Dragon', '击铁龙 猎宝机装', '撃鉄竜リンドブルム', 'Fusion Monster', 'Winged Beast', 'DARK', 8, 2500, 2000, '「阿不思的落胤」＋兽族·兽战士族·鸟兽族怪兽 这个卡名的①②的效果1回合各能使用1次。 ①：融合·同调·超量·连接怪兽的效果发动时才能发动。那个效果无效。那之后，可以让场上1只怪兽回到手卡。 ②：对方回合，这张卡在墓地存在的场合，以自己墓地1只「阿不思的落胤」为对象才能发动。那只怪兽和这张卡之内的1只特殊召唤，另1只除外。'),
(19544412, 'Ring Announcer', '选手入场广播', '選手入場アナウンス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「燃烧拳」卡使用。这个卡名的卡在1回合只能发动1张。 ①：从手卡把1只「燃烧拳击手」怪兽特殊召唤。那之后，可以把最多有自己场上的超量怪兽数量的场上的魔法·陷阱卡破坏。'),
(58641905, 'Ring of Defense', '防御轮', '防御輪', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '陷阱卡的效果的伤害为0。'),
(83555666, 'Ring of Destruction', '破坏轮', '破壊輪', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方回合，以持有对方基本分数值以下的攻击力的对方场上1只表侧表示怪兽为对象才能发动。那只表侧表示怪兽破坏，自己受到那只怪兽的原本攻击力数值的伤害。那之后，给与对方为和自己受到的伤害相同数值的伤害。'),
(20436034, 'Ring of Magnetism', '磁力指轮', '磁力の指輪', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '自己场上的怪兽才可以装备。装备的怪兽攻击力·守备力下降500。对方只能攻击装备了这张卡的怪兽。'),
(30765615, 'Ringowurm, the Dragon Guarding the Hundred Apples', '百檎龙－林果虫', '百檎龍－リンゴブルム', 'Tuner Monster', 'Dragon', 'LIGHT', 2, 100, 1100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在，场上有效果怪兽以外的表侧表示怪兽存在的场合才能发动。这张卡特殊召唤。 ②：自己把同调怪兽同调召唤的回合的自己主要阶段，把墓地的这张卡除外才能发动。在自己场上把1只「百檎衍生物」（幻龙族·光·2星·攻/守100）特殊召唤。自己把这衍生物作为同调素材的场合，可以当作调整使用。'),
(38815069, 'Rinyan, Lightsworn Rogue', '光道贼猫 雷喵', 'ライトロード・シーフ ライニャン', 'Flip Effect Monster', 'Beast', 'LIGHT', 2, 100, 100, '反转：自己墓地中1张名字带有「光道」的怪兽卡回到卡组，从自己的卡组抽1张卡。'),
(51612489, 'Riot''s Reason', '骚动', '騒動', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以场上1只里侧守备表示怪兽为对象才能发动。那只怪兽回到手卡。那之后，这个效果让卡加入手卡的玩家可以从自身手卡把1只怪兽里侧守备表示特殊召唤。 ②：对方怪兽的攻击宣言时，把墓地的这张卡除外才能发动。场上1只里侧守备表示怪兽变成表侧攻击表示。'),
(56410769, 'Ripple Bird', '波纹鸟', '波紋鳥', 'XYZ Monster', 'Winged Beast', 'WIND', 1, 1000, NULL, '1星怪兽×2 ①：只要自己场上的怪兽全部是攻击表示，那些怪兽的攻击力上升500。 ②：只要自己场上的怪兽全部是守备表示，对方不能攻击宣言。 ③：把这张卡1个超量素材取除，以场上1只怪兽为对象才能发动。那只怪兽的表示形式变更。'),
(34016756, 'Riryoku', '原力', 'フォース', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上2只表侧表示怪兽为对象才能发动。直到回合结束时，作为对象的1只怪兽的攻击力变成一半，另1只怪兽的攻击力上升那个数值。'),
(70344351, 'Riryoku Field', '力场', 'フォースフィールド', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '以场上的1只怪兽为对象的魔法的发动无效并破坏。'),
(96661780, 'Riryoku Guardian', '守护者的力量', 'フォース・オブ・ガーディアン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己基本分比对方少的场合，以原本卡名包含「门之守护神」的自己场上1只怪兽为对象才能发动。对方基本分变成一半。那之后，作为对象的怪兽的攻击力上升对方基本分数值。 ②：把墓地的这张卡除外才能发动。自己的卡组·除外状态的「雷魔神-桑迦」「风魔神-修迦」「水魔神-斯迦」的其中1只加入手卡。'),
(300302017, 'Rise of the Fallen', NULL, NULL, 'Skill Card', 'Ishizu Ishtar', NULL, NULL, NULL, NULL, NULL),
(38784726, 'Rise of the Salamangreat', '转生炎兽之降临', '転生炎獣の降臨', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「转生炎兽」仪式怪兽的降临必需。 ①：等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡把1只「转生炎兽」仪式怪兽仪式召唤。自己场上有炎属性连接怪兽存在的场合，自己墓地的「转生炎兽」怪兽也能作为解放的代替而回到卡组。 ②：这张卡被对方的效果破坏的场合才能发动。从手卡把1只「转生炎兽 翠玉鹰」无视召唤条件特殊召唤。'),
(16067089, 'Rise of the Snake Deity', '蛇神降临', '蛇神降臨', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的「毒蛇王 维诺米隆」被战斗以外破坏时才能发动。从手卡·卡组把1只「毒蛇神 维诺米纳迦」特殊召唤。'),
(38044854, 'Rise Rank-Up-Magic Raidraptor''s Force', '起升阶魔法－急袭猛禽之力', 'ЯRUM－レイド・ラプターズ・フォース', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的主要阶段以及对方战斗阶段，以包含场上的怪兽的自己的场上·墓地的「急袭猛禽」超量怪兽2只以上为对象才能发动。把持有和那2只以上的怪兽的阶级合计相同阶级的1只「急袭猛禽」超量怪兽当作超量召唤从额外卡组特殊召唤，把作为对象的怪兽作为那超量素材（作为对象的怪兽持有超量素材的场合，那些也全部作为超量素材）。'),
(19254117, 'Rise to Full Height', '仁王立', '仁王立ち', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以场上1只表侧表示怪兽为对象才能发动。那只怪兽的守备力变成2倍，回合结束时那个守备力变成0。 ②：把墓地的这张卡除外，以自己场上1只怪兽为对象才能发动。这个回合，对方只能向作为对象的怪兽攻击。'),
(25788011, 'Risebell the Star Adjuster', '调星师 莱斯贝尔特', '調星師ライズベルト', 'Effect Monster', 'Psychic', 'WIND', 3, 800, 800, '①：这张卡特殊召唤成功时，以场上1只表侧表示怪兽为对象才能发动。直到回合结束时，那只怪兽的等级上升最多3星。'),
(14812659, 'Risebell the Star Psycher', '觉星师 莱斯贝尔特', '覚星師ライズベルト', 'Effect Monster', 'Psychic', 'WIND', 4, 1500, 1500, '1回合1次，选择场上表侧表示存在的1只怪兽才能发动。选择的怪兽的等级上升1星。这个效果在对方回合也能发动。'),
(45103815, 'Risebell the Summoner', '召唤师 莱斯贝尔特', '召喚師ライズベルト', 'Pendulum Normal Monster', 'Psychic', 'WIND', 3, 800, 800, '非常关心爱护妹妹塞姆贝尔，温和亲切的哥哥莱斯贝尔特。刚过中午的午后他跟妹妹一起读魔术书的时间是每日惯例，见到那俩人和睦的情景让周围人们也自然而然被治愈心灵。'),
(45778932, 'Rising Air Current', '沙漠风暴', 'デザートストーム', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '全部的风属性的怪兽攻击力上升500，守备力下降400。'),
(78211862, 'Rising Energy', '能量提升', 'ライジング・エナジー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：丢弃1张手卡，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升1500。'),
(66947913, 'Rising Fire', '火焰升腾', 'ライジング・オブ・ファイア', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「转生炎兽」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：自己场上没有怪兽存在的场合，以自己墓地1只炎属性怪兽为对象才能把这张卡发动。那只怪兽特殊召唤，把这张卡装备。装备怪兽的攻击力上升500。这张卡从场上离开时那只怪兽破坏。 ②：这张卡被对方的效果破坏的场合才能发动。选场上1只怪兽除外。'),
(94807487, 'Rising Sun Slash', '希望剑一斩', 'ホープ剣スラッシュ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「希望皇 霍普」怪兽才能装备。 ①：装备怪兽不会被效果破坏。 ②：只要这张卡在魔法与陷阱区域存在，每次怪兽的攻击无效，给这张卡放置1个希望剑指示物。装备怪兽的攻击力上升这张卡的希望剑指示物数量×500。 ③：自己场上的装备怪兽把超量素材取除来让效果发动的场合，这张卡可以当作取除的超量素材中的1个使用。'),
(3285551, 'Rite of Aramesir', '菈玛至崇颂之仪', 'アラメシアの儀', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不能把特殊召唤的怪兽以外的场上的怪兽的效果发动。 ①：自己场上没有「勇者衍生物」存在的场合才能发动。在自己场上把1只「勇者衍生物」（天使族·地·4星·攻/守2000）特殊召唤。自己场上没有「命运之旅路」存在的场合，可以再从卡组选1张「命运之旅路」在自己的魔法与陷阱区域表侧表示放置。'),
(30450531, 'Rite of Spirit', '降灵的仪式', '降霊の儀式', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '指定自己墓地里1张名称中含有「守墓」的怪兽卡特殊召唤。这张卡的发动不受「王家长眠之谷」的限制。'),
(57815601, 'Ritual Beast Ambush', '灵兽的骑袭', '霊獣の騎襲', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己的墓地·除外状态的1只「灵兽使」怪兽和1只「精灵兽」怪兽为对象才能发动。那些怪兽守备表示特殊召唤。这张卡的发动后，直到回合结束时自己不是「灵兽」怪兽不能特殊召唤。'),
(22501005, 'Ritual Beast Inheritance', '灵兽的继圣', '霊獣の継聖', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：对方场上的怪兽的攻击力下降自己场上的「灵兽」怪兽的种族种类×200。 ②：把手卡1只「灵兽」怪兽给对方观看才能发动。和那只怪兽种族不同的1只「灵兽」怪兽从卡组加入手卡。那之后，选自己1张手卡丢弃。 ③：自己场上有怪兽2只以上同时特殊召唤的场合，以场上1只怪兽为对象才能发动。那只怪兽的表示形式变更。'),
(8321183, 'Ritual Beast Return', '灵兽的誓还', '霊獣の誓還', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：从手卡把1只「灵兽」怪兽除外，以自己的墓地·除外状态的1只「灵兽」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(11556339, 'Ritual Beast Steeds', '灵兽的连契', '霊獣の連契', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把最多有自己场上的「灵兽」怪兽数量的场上的怪兽破坏。'),
(14513016, 'Ritual Beast Tamer Elder', '灵兽使的长老', '霊獣使いの長老', 'Effect Monster', 'Psychic', 'WIND', 2, 200, 1000, '自己对「灵兽使的长老」1回合只能有1次特殊召唤。 ①：这张卡召唤时适用。这个回合，自己在通常召唤外加上只有1次，自己主要阶段可以把1只「灵兽」怪兽召唤。'),
(87118301, 'Ritual Beast Tamer Lara', '灵兽使 蕾拉', '霊獣使い レラ', 'Effect Monster', 'Psychic', 'WIND', 1, 100, 2000, '自己对「灵兽使 蕾拉」1回合只能有1次特殊召唤。 ①：这张卡召唤的场合，以自己墓地1只「灵兽」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(40907115, 'Ritual Beast Tamer Wen', '灵兽使 温', '霊獣使い ウェン', 'Effect Monster', 'Psychic', 'WIND', 3, 1500, 1000, '自己对「灵兽使 文」1回合只能有1次特殊召唤。 ①：这张卡召唤的场合，以自己的除外状态的1只「灵兽」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(57777714, 'Ritual Beast Tamer Zeframpilica', '英灵兽使－源质美利加', '英霊獣使い－セフィラムピリカ', 'Pendulum Effect Monster', 'Psychic', 'WIND', 3, 1000, 1500, '自己对「英灵兽使-神数心皮莉佳」1回合只能有1次特殊召唤。 ①：这张卡召唤·灵摆召唤时，以「英灵兽使-神数心皮莉佳」以外的自己墓地1只「灵兽」怪兽或「神数」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段破坏。'),
(23166823, 'Ritual Beast Tamer Zefrawendi', '影灵兽使－源质温蒂', '影霊獣使い－セフィラウェンディ', 'Pendulum Effect Monster', 'Psychic', 'WIND', 3, 1500, 1000, '自己对「影灵兽使-神数文蒂」1回合只能有1次特殊召唤。 ①：这张卡召唤·灵摆召唤时才能发动。从自己的额外卡组（表侧）把「影灵兽使-神数文蒂」以外的1只「神数」怪兽加入手卡。'),
(86274272, 'Ritual Beast Ulti-Apelio', '圣灵兽骑 亚边狮', '聖霊獣騎 アペライオ', 'Fusion Monster', 'Pyro', 'WIND', 6, 2600, 400, '「灵兽使」怪兽＋「精灵兽」怪兽 把自己场上的上记的卡除外的场合才能特殊召唤。 ①：这张卡攻击的场合，直到伤害步骤结束时不受其他卡的效果影响。 ②：自己·对方回合，让这张卡回到额外卡组，以自己的除外状态的1只「灵兽使」怪兽和1只「精灵兽」怪兽为对象才能发动。那些怪兽守备表示特殊召唤。'),
(48063985, 'Ritual Beast Ulti-Cannahawk', '圣灵兽骑 神流鹰', '聖霊獣騎 カンナホーク', 'Fusion Monster', 'Thunder', 'WIND', 6, 1400, 1600, '「灵兽使」怪兽＋「精灵兽」怪兽 把自己场上的上记的卡除外的场合才能特殊召唤。 ①：1回合1次，以自己的除外状态的2张「灵兽」卡为对象才能发动。那些卡回到墓地，从卡组把1张「灵兽」卡加入手卡。 ②：自己·对方回合，让这张卡回到额外卡组，以自己的除外状态的1只「灵兽使」怪兽和1只「精灵兽」怪兽为对象才能发动。那些怪兽守备表示特殊召唤。'),
(56655675, 'Ritual Beast Ulti-Gaiapelio', '圣灵兽骑 盖亚边狮', '聖霊獣騎 ガイアペライオ', 'Fusion Monster', 'Psychic', 'LIGHT', 10, 3200, 2100, '「圣灵兽骑」怪兽＋「灵兽使」怪兽＋「精灵兽」怪兽 把自己场上的上记的卡除外的场合才能特殊召唤。 ①：这个方法特殊召唤的这张卡得到以下效果。 ●怪兽的效果·魔法·陷阱卡发动时，从手卡把1张「灵兽」卡除外才能发动。那个发动无效并破坏。'),
(58811192, 'Ritual Beast Ulti-Kimunfalcos', '圣灵兽骑 奇牟隼', '聖霊獣騎 キムンファルコス', 'Link Monster', 'Psychic', 'WIND', NULL, 1800, NULL, '「灵兽」怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：这张卡所连接区的「灵兽」怪兽的攻击力·守备力上升600。 ②：从自己墓地把1张「灵兽」卡除外才能发动。进行手卡1只「灵兽」怪兽的召唤。 ③：自己·对方回合，让这张卡回到额外卡组，以自己的除外状态的1只「灵兽使」怪兽和1只「精灵兽」怪兽为对象才能发动。那些怪兽守备表示特殊召唤。'),
(69718652, 'Ritual Beast Ulti-Nochiudrago', '圣灵兽骑 野宙龙', '聖霊獣騎 ノチウドラゴ', 'Fusion Monster', 'Wyrm', 'LIGHT', 7, 2400, 1900, '「灵兽使」怪兽＋「精灵兽」怪兽 把自己的场上·墓地的上记的卡除外的场合才能特殊召唤。自己对「圣灵兽骑 星龙」1回合只能有1次特殊召唤。 ①：只要这张卡在怪兽区域存在，对方不能把自己场上的其他的「灵兽」怪兽作为效果的对象。 ②：自己·对方回合，让这张卡回到额外卡组，以自己的除外状态的1只「灵兽」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽不能直接攻击。'),
(12678870, 'Ritual Beast Ulti-Pettlephin', '圣灵兽骑 别都豚', '聖霊獣騎 ペトルフィン', 'Fusion Monster', 'Aqua', 'WIND', 6, 200, 2800, '「灵兽使」怪兽＋「精灵兽」怪兽 把自己场上的上记的卡除外的场合才能特殊召唤。 ①：场上的这张卡不会被效果破坏。 ②：自己·对方回合，让这张卡回到额外卡组，以自己的除外状态的1只「灵兽使」怪兽和1只「精灵兽」怪兽为对象才能发动。那些怪兽守备表示特殊召唤。'),
(96113307, 'Ritual Beast Ulti-Reirautari', '圣灵兽骑 蕾伊拉呗里', '聖霊獣騎 レイラウタリ', 'Link Monster', 'Psychic', 'WIND', NULL, 2600, NULL, '效果怪兽3只以上 这个卡名的②③的效果1回合各能使用1次。 ①：只要这张卡在怪兽区域存在，双方不能为让卡的效果发动而把卡解放。 ②：以自己的除外状态的1张「灵兽」卡为对象才能发动。那张卡回到手卡·额外卡组。那之后，可以进行手卡1只「灵兽」怪兽的召唤。 ③：对方回合，以自己场上1张「灵兽」卡和对方场上1张卡为对象才能发动。那些卡除外。'),
(75457624, 'Ritual Beast''s Bond', '灵兽的羁绊', '霊獣の相絆', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：把自己场上2只表侧表示的「灵兽」怪兽除外才能发动。从额外卡组把1只「灵兽」怪兽无视召唤条件特殊召唤。'),
(54094821, 'Ritual Buster', '仪式破势', 'リチュアルバスター', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己或者对方仪式召唤成功时才能发动。直到下次的自己回合的准备阶段，对方不能作魔法·陷阱卡的发动以及那个效果的发动。'),
(25796442, 'Ritual Cage', '仪式之槛', '儀式の檻', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，自己的仪式怪兽的战斗发生的对自己的战斗伤害变成0。 ②：只要这张卡在魔法与陷阱区域存在，自己场上的仪式怪兽不会成为怪兽的效果的对象，不会被怪兽的效果破坏。'),
(300302002, 'Ritual Ceremony', NULL, NULL, 'Skill Card', 'Emma', NULL, NULL, NULL, NULL, NULL),
(65450690, 'Ritual Foregone', '限定解除', '限定解除', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '支付1000基本分。从手卡特殊召唤1只仪式怪兽。这个效果特殊召唤的仪式怪兽不能攻击，结束阶段时破坏。「限定解除」在1回合只能发动1张。'),
(300204001, 'Ritual of Black Mastery', NULL, NULL, 'Skill Card', 'Yami Yugi', NULL, NULL, NULL, NULL, NULL),
(52913738, 'Ritual of Destruction', '破灭的仪式', '破滅の儀式', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「破灭之魔王 加兰道夫」的降临必需。必须从手卡·自己场上把等级合计直到7以上的怪兽解放。可以把自己墓地存在的这张卡从游戏中除外，这个回合自己场上表侧表示存在的仪式怪兽战斗破坏的怪兽不送去墓地回到卡组最上面。'),
(60234913, 'Ritual of Grace', '救世的仪式', '救世の儀式', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「救世之美神 诺斯维姆科」的降临必需。必须从手卡·自己场上把等级合计直到7以上的怪兽解放。可以把自己墓地存在的这张卡从游戏中除外，这个回合自己场上表侧表示存在的1只仪式怪兽不会成为魔法·陷阱·效果怪兽的效果的对象。'),
(70105073, 'Ritual of the Matador', '斗牛士降临之仪式 黑暗游行', 'マタドール降臨の儀式 ダーク・パセオ', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：等级合计直到6以上的自己的手卡·场上的怪兽解放，从手卡把「恶魔斗牛士」仪式召唤。 ②：把墓地的这张卡除外才能发动。从手卡把仪式怪兽以外的1只「恶魔」怪兽特殊召唤。'),
(34334692, 'Ritual Raven', '仪式的供物', '儀式の供物', 'Effect Monster', 'Fiend', 'DARK', 1, 300, 300, '暗属性的仪式怪兽特殊召唤的场合，可以让这1张卡作为仪式召唤的祭品使用。'),
(95658967, 'Ritual Sanctuary', '祝福教会－仪式圣堂', '祝福の教会－リチューアル・チャーチ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡丢弃1张魔法卡才能发动。从卡组把1只光属性仪式怪兽或者1张仪式魔法卡加入手卡。 ②：让自己墓地的魔法卡任意数量回到卡组，以持有和回去数量相同等级的自己墓地1只天使族·光属性怪兽为对象才能发动。那只怪兽特殊召唤。'),
(9145181, 'Ritual Sealing', '仪式降临封印之书', '儀式降臨封印の書', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '场上表侧表示存在的1只仪式怪兽破坏。'),
(54351224, 'Ritual Weapon', '仪式武器', 'リチュアル・ウェポン', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '6星以下的仪式怪兽才能装备。装备怪兽的攻击力·守备力上升1500。'),
(90846359, 'Rivalry of Warlords', '群雄割据', '群雄割拠', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，双方场上各自只能有1种类的种族的怪兽表侧表示存在。双方玩家在自身场上的表侧表示怪兽的种族是2种类以上的场合直到变成1种类为止必须送去墓地。'),
(71971554, 'Road Synchron', '王道同步士', 'ロード・シンクロン', 'Tuner Monster', 'Machine', 'LIGHT', 4, 1600, 800, '①：把这张卡作为「王道战士」以外的同调怪兽的素材的场合，当作这张卡的等级下降2星的等级使用。 ②：这张卡攻击的场合，那次伤害步骤结束时发动。这张卡的等级直到回合结束时上升1星。'),
(2322421, 'Road Warrior', '王道战士', 'ロード・ウォリアー', 'Synchro Monster', 'Warrior', 'LIGHT', 8, 3000, 1500, '「王道同调士」＋调整以外的怪兽2只以上 ①：1回合1次，自己主要阶段才能发动。从卡组把1只2星以下的战士族·机械族怪兽特殊召唤。'),
(17725109, 'Roar of the Blue-Eyed Dragons', '青眼龙轰临', '青眼龍轟臨', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己的卡组·墓地·除外状态的1只「青眼」怪兽守备表示特殊召唤。自己场上没有「青眼白龙」存在的场合，这个效果不是「青眼白龙」不能特殊召唤。这个回合，自己不是龙族怪兽不能从额外卡组特殊召唤。 ②：把墓地的这张卡除外才能发动。包含「青眼」怪兽的自己的手卡·场上的怪兽作为融合素材，把1只融合怪兽融合召唤。'),
(56339050, 'Roar of the Earthbound Immortal', '地缚神的咆哮', '地縛神の咆哮', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方怪兽的攻击宣言时，攻击怪兽的攻击力比自己场上表侧表示存在的名字带有「地缚神」的怪兽的攻击力低的场合，把那1只攻击怪兽破坏，给与对方基本分破坏怪兽的攻击力一半数值的伤害。这个效果1回合只能使用1次。'),
(4587638, 'Roaring Earth', '狂吠的大地', '吠え猛る大地', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上在的兽族怪兽向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。这个效果适用给与对方基本分战斗伤害时，对方场上表侧表示存在的1只怪兽的攻击力·守备力下降500。'),
(19066538, 'Roaring Ocean Snake', '轰鸣的大海蛇', '轟きの大海蛇', 'Fusion Monster', 'Aqua', 'WATER', 6, 2100, 1800, '「魔法灯」＋「兵主部」'),
(88279736, 'Robbin'' Goblin', '哥布林拦路贼', '追い剥ぎゴブリン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上的怪兽每次造成对方玩家的战斗伤害时，对方随机丢弃1张手卡。'),
(83258273, 'Robbin'' Zombie', '僵尸拦路贼', '追い剥ぎゾンビ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '每当自己场上的怪兽对对方造成战斗伤害时，对方将其卡组最上面1张卡送去墓地。'),
(92421852, 'Robolady', '稀有金属女郎', 'レアメタル・レディ', 'Normal Monster', 'Machine', 'EARTH', 3, 450, 900, '全身覆盖着金属装甲的女战士。与「稀有金属战士」融合将提升力量。'),
(38601126, 'Robot Buster Destruction Sword', '破坏剑-武器破坏之剑', '破壊剣－アームズバスターブレード', 'Effect Monster', 'Machine', 'DARK', 4, 1600, 1200, '①：自己主要阶段以自己场上1只「破坏之剑士」为对象才能发动。从自己的手卡·场上把这只怪兽当作装备卡使用给那只自己怪兽装备。 ②：这张卡装备中的场合，对方场上的已是表侧表示存在的魔法·陷阱卡不能把效果发动。 ③：把装备的这张卡送去墓地才能发动。这张卡装备过的怪兽的攻击力直到回合结束时上升1000。'),
(44203504, 'Robotic Knight', '机械军曹', '機械軍曹', 'Normal Monster', 'Machine', 'FIRE', 4, 1600, 1800, '侍从机械王的机械族的司令官。统率机械部队的攻击性用兵而很有名。'),
(38916461, 'Roboyarou', '稀有金属战士', 'レアメタル・ソルジャー', 'Normal Monster', 'Machine', 'EARTH', 3, 900, 450, '全身覆盖着金属装甲的战士。与「稀有金属女郎」融合将提升力量。'),
(28143906, 'Roc from the Valley of Haze', '霞谷的大怪鸟', '霞の谷の大怪鳥', 'Effect Monster', 'Winged Beast', 'WIND', 6, 2400, 1400, '这张卡从手卡送去墓地时，这张卡加入卡组并且洗切。'),
(36187051, 'Rock Band Xenoguitar', '岩乐团之美技－磷钇吉他手', '巌帯の美技－ゼノギタム', 'Effect Monster', 'Rock', 'EARTH', 4, 1000, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡被送去墓地的场合，以「岩带的美技-磷钇矿吉他手」以外的自己墓地1只岩石族怪兽为对象才能发动。那只怪兽加入手卡。那之后，选1张手卡在卡组最上面放置。 ②：这张卡从场上·墓地除外的场合才能发动。从卡组把1只岩石族怪兽送去墓地。'),
(20781762, 'Rock Bombardment', '投石攻击', '岩投げアタック', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己卡组1只岩石族怪兽送去墓地。给与对方基本分500分的伤害。之后洗切卡组。'),
(28168628, 'Rock of the Vanquisher', '斗神的虚像', '闘神の虚像', 'Link Monster', 'Rock', 'DARK', NULL, NULL, NULL, '「征服斗魂」怪兽1只 这张卡不能作为连接素材。这个卡名的②的效果1回合只能使用1次。 ①：只要自己场上有「征服斗魂」怪兽存在，对方只能选择自己场上的攻击力最高的怪兽作为攻击对象。 ②：自己·对方的主要阶段，可以从以下效果选择1个发动。 ●从手卡把1只「征服斗魂」怪兽特殊召唤。 ●从自己墓地选1只「征服斗魂」怪兽加入手卡。'),
(68846917, 'Rock Ogre Grotto #1', '岩窟魔人', '岩窟魔人オーガ・ロック', 'Normal Monster', 'Rock', 'EARTH', 3, 800, 1200, '岩石之躯成就高强的守备力。挥起巨腕时务必警惕。'),
(62193699, 'Rock Ogre Grotto #2', '大地战士', 'ウォー・アース', 'Normal Monster', 'Rock', 'EARTH', 3, 700, 1400, '岩石聚集而成的石像。将对方石化后破坏。'),
(57946551, 'Rock Scales', '岩鳞鱼', 'ロック・スケイル', 'Effect Monster', 'Fish', 'WATER', 5, 2100, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合，以这张卡以外的场上1只表侧表示怪兽为对象才能发动。那只表侧表示怪兽当作装备卡使用给这张卡装备。 ②：种族·属性和这张卡的效果装备的怪兽卡相同的对方怪兽和这张卡进行战斗的伤害步骤开始时才能发动。那只对方怪兽破坏。'),
(82818645, 'Rock Spirit', '岩石之精灵', '岩石の精霊', 'Normal Monster', 'Spellcaster', 'EARTH', 5, 1650, 1900, '指轮般的岩石精灵。攻击与守备力都很强。'),
(79850798, 'Rocket Arrow Express', '爆走特急 火箭飞矢', '爆走特急ロケット・アロー', 'Effect Monster', 'Machine', 'EARTH', 10, 5000, NULL, '这张卡不能通常召唤。自己场上没有卡存在的场合才能特殊召唤。把这张卡特殊召唤的回合，自己不能进行战斗阶段。这张卡的控制者在每次自己准备阶段把手卡全部送去墓地。或者不送去墓地让这张卡破坏。 ①：只要这张卡在怪兽区域存在，自己不能把魔法·陷阱·怪兽的效果发动，不能把卡盖放。'),
(13317419, 'Rocket Hand', '火箭手', 'ロケットハンド', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上1只攻击力800以上的攻击表示怪兽为对象才能把这张卡发动。这张卡当作攻击力上升800的装备卡使用给那只怪兽装备。 ②：把装备的这张卡送去墓地，以场上1张表侧表示的卡为对象才能发动。那张卡破坏。那之后，这张卡装备过的怪兽攻击力变成0，不能把表示形式变更。'),
(46354113, 'Rocket Hermos Cannon', '火箭赫谟炮', 'ロケット・ヘルモス・キャノン', 'Fusion Monster', 'Warrior', 'LIGHT', 4, 1500, 1300, '这张卡在用「赫谟之爪」的效果把自己的手卡·场上的战士族怪兽送去墓地的场合才能特殊召唤。 ①：这张卡特殊召唤成功的场合，以这张卡以外的场上1只怪兽为对象发动。这张卡当作装备卡使用给那只怪兽装备。 ②：用这张卡的效果把这张卡装备的怪兽在同1次的战斗阶段中可以作2次攻击，向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(53890795, 'Rocket Jumper', '火箭弹跳手', 'ロケット・ジャンパー', 'Effect Monster', 'Rock', 'EARTH', 3, 1000, 800, '当对方场上只有守备表示的怪兽存在时，这张卡可以对对方进行直接攻击。'),
(27863269, 'Rocket Pilder', '火箭穿心器', 'ロケット・パイルダー', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽攻击的场合，装备怪兽不会被战斗破坏。装备怪兽进行攻击的伤害步骤结束时，受到装备怪兽的攻击的怪兽的攻击力直到结束阶段时下降装备怪兽的攻击力数值。'),
(30860696, 'Rocket Warrior', '火箭战士', 'ロケット戦士', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1500, 1300, '①：自己战斗阶段中，这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害变成0。 ②：这张卡向怪兽攻击的伤害计算后发动。攻击对象怪兽的攻击力直到回合结束时下降500。'),
(51987572, 'Rockstone Token', '岩石战士', 'ロックストーン・ウォリアー', 'Token', 'Rock', NULL, NULL, NULL, NULL, NULL),
(51987571, 'Rockstone Warrior', '岩石战士', 'ロックストーン・ウォリアー', 'Effect Monster', 'Rock', 'EARTH', 4, 1800, 1600, '这张卡的战斗发生的对自己的战斗伤害变成0。这张卡的攻击让这张卡被战斗破坏送去墓地时，在自己场上把2只「岩石衍生物」（岩石族·地·1星·攻/守0）特殊召唤。这衍生物不能为上级召唤而解放。'),
(95515060, 'Rod of Silence - Kay''est', '静寂之杖-波纹', '静寂のロッド－ケースト', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备这张卡的怪兽守备力上升500分。以装备怪兽为对象的这张卡以外的魔法卡的效果无效并破坏。'),
(94793422, 'Rod of the Mind''s Eye', '心眼之矛', '心眼の鉾', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '当装备这张卡的怪兽对对方造成战斗伤害时，战斗伤害的数值变为1000点。'),
(13478040, 'Rodenut', '橡子松鼠', 'ドングリス', 'Effect Monster', 'Beast', 'EARTH', 1, 100, 100, '每次对方把怪兽特殊召唤，给这张卡放置1个橡子指示物。可以把这张卡放置的1个橡子指示物取除，选择对方场上存在的1只怪兽破坏。'),
(91939608, 'Rogue Doll', '神圣人偶', 'ホーリー・ドール', 'Normal Monster', 'Spellcaster', 'LIGHT', 4, 1600, 1000, '操纵神圣力量的人偶。在黑暗之中攻击力很强。'),
(44640691, 'Rogue of Endymion', '恩底弥翁之刺客', 'ローグ・オブ・エンディミオン', 'Effect Monster', 'Spellcaster', 'FIRE', 3, 1500, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合发动。给这张卡放置1个魔力指示物。 ②：把这张卡1个魔力指示物取除，从手卡丢弃1只魔法师族怪兽才能发动。从卡组选1张永续魔法卡在自己的魔法与陷阱区域盖放。这个回合，自己不能把这个效果盖放的卡以及那些同名卡的效果发动。'),
(67127799, 'Rokket Caliber', '枪弹口径者', 'ヴァレット・キャリバー', 'Tuner Monster', 'Dragon', 'DARK', 4, 1700, 100, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以从手卡往作为暗属性连接怪兽所连接区的自己场上特殊召唤。 ②：把这张卡解放才能发动。从手卡把「弹丸口径龙」以外的1只龙族·机械族的暗属性怪兽特殊召唤。'),
(77189532, 'Rokket Coder', '枪弹代码者', 'ヴァレット・コーダー', 'Effect Monster', 'Cyberse', 'DARK', 4, 1700, 300, '这个卡名的①③的效果1回合各能使用1次。 ①：把自己场上的电子界族怪兽作为「码语者」怪兽的连接素材的场合，手卡的这张卡也能作为连接素材。 ②：把这张卡在「枪管」怪兽的连接召唤使用的场合，可以把这张卡的种族当作龙族使用。 ③：把自己场上的这张卡作为「枪管」怪兽的连接素材的场合，手卡的暗属性怪兽也能有最多1只作为连接素材。'),
(98937206, 'Rokket Detonator', '枪弹导爆者', 'ヴァレット・デトネイター', 'Effect Monster', 'Dragon', 'DARK', 7, 1800, 2500, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有龙族·暗属性连接怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：以自己的魔法与陷阱区域1张龙族·暗属性怪兽卡为对象才能发动。那张卡特殊召唤。这个效果特殊召唤的怪兽不能攻击，效果无效化。这个效果的发动后，直到回合结束时自己不是暗属性怪兽不能从额外卡组特殊召唤。'),
(25554552, 'Rokket Loader', '枪弹装填者', 'ヴァレット・ローダー', 'Effect Monster', 'Dragon', 'DARK', 4, 1500, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1只龙族·暗属性·7星怪兽加入手卡。这个效果的发动后，直到回合结束时自己不是暗属性怪兽不能从额外卡组特殊召唤。 ②：把墓地的这张卡除外，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的属性直到回合结束时变成暗属性。'),
(5969957, 'Rokket Recharger', '枪弹填充者', 'ヴァレット・リチャージャー', 'Effect Monster', 'Dragon', 'DARK', 4, NULL, 2100, '这个卡名的①的效果1回合只能使用1次。 ①：从额外卡组特殊召唤的自己场上的表侧表示的暗属性怪兽被战斗·效果破坏的场合，把手卡·场上的这张卡送去墓地，以那些破坏的怪兽之内的1只为对象才能发动。原本卡名和那只怪兽不同的1只暗属性怪兽从自己墓地特殊召唤。 ②：只要从额外卡组特殊召唤的暗属性怪兽在自己场上存在，对方怪兽不能选择这张卡作为攻击对象。'),
(48355999, 'Rokket Synchron', '枪弹同步士', 'ヴァレット・シンクロン', 'Tuner Monster', 'Dragon', 'DARK', 1, NULL, NULL, '①：这张卡召唤时，以自己墓地1只5星以上的龙族·暗属性怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化，结束阶段破坏。这个效果的发动后，直到回合结束时自己不是暗属性怪兽不能从额外卡组特殊召唤。'),
(68464358, 'Rokket Tracer', '枪弹曳光者', 'ヴァレット・トレーサー', 'Tuner Monster', 'Dragon', 'DARK', 4, 1600, 1000, '这个卡名的效果1回合只能使用1次。 ①：自己·对方回合，以自己场上1张表侧表示卡为对象才能发动。那张卡破坏，从卡组把「弹丸曳光龙」以外的1只「弹丸」怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是暗属性怪兽不能从额外卡组特殊召唤。'),
(91597389, 'Roll Out!', '骑乘！', 'ゲットライド！', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地存在的1只同盟怪兽，给自己场上表侧表示存在的可以装备的怪兽装备。'),
(44956694, 'ROM Cloudia', 'ROM云雌羊', 'ROMクラウディア', 'Effect Monster', 'Cyberse', 'DARK', 4, 1800, NULL, '①：这张卡召唤成功时，以「ROM云雌羊」以外的自己墓地1只电子界族怪兽为对象才能发动。那只怪兽加入手卡。 ②：这张卡被战斗·效果破坏的场合才能发动。从卡组把「ROM云雌羊」以外的1只4星以下的电子界族怪兽特殊召唤。'),
(1357146, 'Ronintoadin', '粹蛙', '粋カエル', 'Effect Monster', 'Aqua', 'WATER', 2, 100, 2000, '这张卡不能作为同调素材。 ①：这张卡只要在怪兽区域存在，卡名当作「死亡青蛙」使用。 ②：这张卡在墓地存在的场合，从自己墓地把1只「青蛙」怪兽除外才能发动。这张卡特殊召唤。'),
(48214588, 'Rookie Fur Hire', '新风的空牙团', '新風の空牙団', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不用「空牙团」怪兽不能攻击宣言。 ①：把自己场上1只怪兽解放才能发动。比那只怪兽等级高1星或低1星的1只「空牙团」怪兽从手卡·卡组特殊召唤。'),
(86028783, 'Rookie Warrior Lady', '新锐的女战士', '新鋭の女戦士', 'Effect Monster', 'Warrior', 'EARTH', 3, 1000, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的其他的战士族怪兽和对方的表侧表示怪兽进行战斗的攻击宣言时，把手卡·场上的这张卡送去墓地才能发动。那只对方怪兽的攻击力直到回合结束时下降那自身原本攻击力数值。 ②：把墓地的这张卡除外，以自己墓地1只战士族·地属性怪兽为对象才能发动。那只怪兽加入手卡。'),
(300302039, 'Room for Growth', NULL, NULL, 'Skill Card', 'Syrus Truesda', NULL, NULL, NULL, NULL, NULL),
(39004808, 'Root Water', '根潭鱼人', 'ルート・ウォーター', 'Normal Monster', 'Fish', 'WATER', 3, 900, 800, '潜伏在海里的半鱼人，掀起黑暗浪潮袭击。'),
(93382620, 'Rope of Life', '命之纲', '命の綱', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '当自己的怪兽因战斗送去墓地时，将手卡全部丢弃发动这张卡，那只怪兽的攻击力上升800，并且特殊召唤上场。'),
(81146288, 'Rosaria, the Stately Fallen Angel', '大凛魔天使 蔷薇仙', '大凛魔天使ローザリアン', 'Effect Monster', 'Plant', 'EARTH', 8, 2900, 2400, '这张卡不能通常召唤。从自己的手卡和墓地把7星以上的植物族怪兽各1只从游戏中除外的场合可以特殊召唤。1回合1次，自己的主要阶段时才能发动。这张卡以外的场上表侧表示存在的卡的效果直到结束阶段时无效。');